using System.Collections.Generic;
using GTA;
using GTA.Native;
using LemonUI.Menus;
using TitanTrainer.Utils;
namespace TitanTrainer.UI
{
    public sealed class WeaponsMenu : BaseMenu
    {
        private readonly NotificationService _notifications; private readonly System.Action _goBack; private readonly List<NativeMenu> _allMenus=new List<NativeMenu>(); public NativeMenu[] AllMenus=>_allMenus.ToArray();
        private static readonly WeaponEntry[] Weapons={new WeaponEntry("Pistol","WEAPON_PISTOL",250),new WeaponEntry("Combat Pistol","WEAPON_COMBATPISTOL",250),new WeaponEntry("AP Pistol","WEAPON_APPISTOL",250),new WeaponEntry("Heavy Pistol","WEAPON_HEAVYPISTOL",250),new WeaponEntry("Micro SMG","WEAPON_MICROSMG",500),new WeaponEntry("SMG","WEAPON_SMG",500),new WeaponEntry("Assault Rifle","WEAPON_ASSAULTRIFLE",500),new WeaponEntry("Carbine Rifle","WEAPON_CARBINERIFLE",500),new WeaponEntry("Advanced Rifle","WEAPON_ADVANCEDRIFLE",500),new WeaponEntry("Pump Shotgun","WEAPON_PUMPSHOTGUN",150),new WeaponEntry("Sawed-Off Shotgun","WEAPON_SAWNOFFSHOTGUN",150),new WeaponEntry("Bullpup Shotgun","WEAPON_BULLPUPSHOTGUN",150),new WeaponEntry("Sniper Rifle","WEAPON_SNIPERRIFLE",100),new WeaponEntry("Heavy Sniper","WEAPON_HEAVYSNIPER",100),new WeaponEntry("Grenade Launcher","WEAPON_GRENADELAUNCHER",50),new WeaponEntry("RPG","WEAPON_RPG",50),new WeaponEntry("Minigun","WEAPON_MINIGUN",1000),new WeaponEntry("Grenade","WEAPON_GRENADE",25),new WeaponEntry("Sticky Bomb","WEAPON_STICKYBOMB",25),new WeaponEntry("Knife","WEAPON_KNIFE",1),new WeaponEntry("Bat","WEAPON_BAT",1),new WeaponEntry("Crowbar","WEAPON_CROWBAR",1)};
        public WeaponsMenu(NotificationService notifications,System.Action goBack):base("Titan Trainer","Weapons & Loadouts")
        {
            _notifications=notifications;_goBack=goBack;_allMenus.Add(Menu);
            var pistols=MenuNavigation.CreateChild(Menu,"Pistols","Handguns and sidearms",_allMenus);var smgRifles=MenuNavigation.CreateChild(Menu,"SMGs & Rifles","Automatic weapons and assault rifles",_allMenus);var shotSniper=MenuNavigation.CreateChild(Menu,"Shotguns & Snipers","Close-range and precision weapons",_allMenus);var heavy=MenuNavigation.CreateChild(Menu,"Heavy Weapons & Explosives","Launchers, miniguns, and explosives",_allMenus);var melee=MenuNavigation.CreateChild(Menu,"Melee Weapons","Unarmed and melee options",_allMenus);var loadout=MenuNavigation.CreateChild(Menu,"Loadout & Ammo","Full loadouts, ammunition, and weapon cleanup",_allMenus);
            foreach(var child in new[]{pistols,smgRifles,shotSniper,heavy,melee,loadout})MenuNavigation.AddBack(child,Menu,_allMenus);
            AddWeapon(melee,new WeaponEntry("Unarmed",null,0));foreach(var w in Weapons){var target=w.Name.Contains("Pistol")?pistols:w.Name.Contains("SMG")||w.Name.Contains("Rifle")&&!w.Name.Contains("Sniper")?smgRifles:w.Name.Contains("Shotgun")||w.Name.Contains("Sniper")?shotSniper:w.Name.Contains("Grenade")||w.Name.Contains("RPG")||w.Name.Contains("Minigun")||w.Name.Contains("Sticky")?heavy:melee;AddWeapon(target,w);}
            AddAction(loadout,"Give Standard Arsenal","Equip the standard selection of weapons",()=>{foreach(var w in Weapons)GiveWeapon(w,false);_notifications?.NotifySuccess("Standard arsenal granted");});
            AddAction(loadout,"Refill All Ammo","Refill ammunition for the selected weapon",()=>{var ped=Game.Player.Character;if(ped==null||!ped.Exists())return;Function.Call(Hash.SET_AMMO_IN_CLIP,ped.Handle,Function.Call<int>(Hash.GET_SELECTED_PED_WEAPON,ped.Handle),999);Function.Call(Hash.ADD_AMMO_TO_PED,ped.Handle,Function.Call<int>(Hash.GET_SELECTED_PED_WEAPON,ped.Handle),9999);_notifications?.NotifySuccess("Current weapon ammo refilled");});
            var infinite=new NativeCheckboxItem("Infinite Ammo Clip",false);infinite.CheckboxChanged+=(s,e)=>{var ped=Game.Player.Character;if(ped!=null&&ped.Exists())Function.Call(Hash.SET_PED_INFINITE_AMMO_CLIP,ped.Handle,infinite.Checked);_notifications?.NotifyInfo(infinite.Checked?"Infinite ammo clip enabled":"Infinite ammo clip disabled");};loadout.Add(infinite);
            AddAction(loadout,"Remove All Weapons","Remove every weapon from the player",()=>{var ped=Game.Player.Character;if(ped!=null&&ped.Exists()){Function.Call(Hash.REMOVE_ALL_PED_WEAPONS,ped.Handle,true);_notifications?.NotifySuccess("Weapons removed");}});
        }
        private void AddWeapon(NativeMenu target,WeaponEntry entry){var item=new NativeItem(entry.Name,entry.WeaponName==null?"Select unarmed":"Equip with ammunition");item.Activated+=(s,e)=>GiveWeapon(entry);target.Add(item);}
        private void AddAction(NativeMenu target,string name,string desc,System.Action action){var item=new NativeItem(name,desc);item.Activated+=(s,e)=>action();target.Add(item);}
        private void GiveWeapon(WeaponEntry entry,bool notify=true){var ped=Game.Player.Character;if(ped==null||!ped.Exists()){_notifications?.NotifyError("Player character is unavailable");return;}if(string.IsNullOrEmpty(entry.WeaponName)){Function.Call(Hash.SET_CURRENT_PED_WEAPON,ped.Handle,Function.Call<int>(Hash.GET_HASH_KEY,"WEAPON_UNARMED"),true);if(notify)_notifications?.NotifyInfo("Unarmed selected");return;}int hash=Function.Call<int>(Hash.GET_HASH_KEY,entry.WeaponName);Function.Call(Hash.GIVE_WEAPON_TO_PED,ped.Handle,hash,entry.Ammo,false,true);Function.Call(Hash.SET_PED_AMMO,ped.Handle,hash,entry.Ammo);if(notify)_notifications?.NotifySuccess(entry.Name+" equipped");}
        public override void Show(){MenuNavigation.Hide(_allMenus);Menu.Visible=true;}public override void Hide()=>MenuNavigation.Hide(_allMenus);
        private sealed class WeaponEntry{public string Name{get;}public string WeaponName{get;}public int Ammo{get;}public WeaponEntry(string n,string w,int a){Name=n;WeaponName=w;Ammo=a;}}
    }
}
